import { useRef, useState, type FormEvent } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

type RegistrationData = {
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY: RegistrationData = { email: '', phone: '', city: '', street: '', zip: '' };

function validate(step: number, data: RegistrationData): Partial<Record<keyof RegistrationData, string>> {
  if (step === 0) {
    return {
      email: !data.email.trim()
        ? 'Укажите электронную почту'
        : !data.email.includes('@')
          ? 'Адрес должен содержать символ @'
          : undefined,
      phone: data.phone.trim().length < 10 ? 'Укажите номер из 10 цифр' : undefined,
    };
  }
  if (step === 1) {
    return {
      city: !data.city.trim() ? 'Укажите город' : undefined,
      street: !data.street.trim() ? 'Укажите улицу и дом' : undefined,
      zip: !/^\d{6}$/.test(data.zip.trim()) ? 'Индекс из 6 цифр' : undefined,
    };
  }
  return {};
}

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY);
  const [showErrors, setShowErrors] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);

  const errors = validate(step, data);
  const hasErrors = Object.values(errors).some(Boolean);
  const isLast = step === STEPS.length - 1;

  const set = (key: keyof RegistrationData) => (event: { target: { value: string } }) => {
    setData((prev) => ({ ...prev, [key]: event.target.value }));
  };

  const goTo = (next: number) => {
    setShowErrors(false);
    setStep(next);
    panelRef.current?.focus();
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (hasErrors) {
      setShowErrors(true);
      return;
    }
    if (isLast) {
      onSubmit(data);
      return;
    }
    goTo(step + 1);
  };

  const errorOf = (key: keyof RegistrationData) => (showErrors ? errors[key] : undefined);

  return (
    <form
      onSubmit={handleSubmit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 520,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={STEPS} current={step} aria-label="Шаги регистрации" />

      <div
        ref={panelRef}
        tabIndex={-1}
        role="group"
        aria-label={STEPS[step].label}
        style={{ display: 'flex', flexDirection: 'column', gap: 16 }}
      >
        {step === 0 && (
          <>
            <JxInputField
              label="Электронная почта"
              type="email"
              autoComplete="email"
              required
              value={data.email}
              onChange={set('email')}
              errorText={errorOf('email')}
              helperText="На неё придёт письмо для подтверждения"
            />
            <JxInputField
              label="Телефон"
              type="tel"
              inputMode="numeric"
              autoComplete="tel"
              prefix="+7"
              required
              placeholder="9001234567"
              value={data.phone}
              onChange={set('phone')}
              errorText={errorOf('phone')}
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxInputField
              label="Город"
              autoComplete="address-level2"
              required
              value={data.city}
              onChange={set('city')}
              errorText={errorOf('city')}
            />
            <JxInputField
              label="Улица и дом"
              autoComplete="street-address"
              required
              value={data.street}
              onChange={set('street')}
              errorText={errorOf('street')}
            />
            <JxInputField
              label="Почтовый индекс"
              inputMode="numeric"
              autoComplete="postal-code"
              required
              placeholder="101000"
              value={data.zip}
              onChange={set('zip')}
              errorText={errorOf('zip')}
            />
          </>
        )}

        {step === 2 && (
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '12px 16px',
              margin: 0,
              padding: 16,
              background: 'var(--jx-surface-2)',
              border: '1px solid var(--jx-border)',
              borderRadius: 'var(--jx-r)',
            }}
          >
            {[
              ['Почта', data.email],
              ['Телефон', `+7 ${data.phone}`],
              ['Город', data.city],
              ['Адрес', data.street],
              ['Индекс', data.zip],
            ].map(([term, value]) => (
              <div key={term} style={{ display: 'contents' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>{term}</dt>
                <dd style={{ margin: 0, color: 'var(--jx-text)', overflowWrap: 'anywhere' }}>{value}</dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8 }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={() => goTo(step - 1)}>
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

